import { css, props } from "@kirana-style/core"
import { Popup } from "menu-lib"

const styles = { button: css({ paddingInline: "1rem" }) }

// Reads `sx`, as a Kirana library's components do: not reported.
export function Button({ sx, ...rest }) {
  return <button {...rest} {...props(styles.button, sx)} />
}

// Spreads `sx` unread onto an installed component: reported one module away, as a component of
// the application's own would be.
export function Menu({ ...rest }) {
  return <Popup {...rest} />
}
